package vn.boardinghub.modules.auth;import vn.boardinghub.modules.user.*;import vn.boardinghub.security.jwt.JwtService;import org.junit.jupiter.api.Test;import org.springframework.security.crypto.password.PasswordEncoder;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class AuthServiceTest{@Test void registerRejectsDuplicateEmail(){UserRepository repo=mock(UserRepository.class);PasswordEncoder encoder=mock(PasswordEncoder.class);JwtService jwt=mock(JwtService.class);when(repo.existsByEmailIgnoreCase("a@b.com")).thenReturn(true);AuthService service=new AuthService(repo,encoder,jwt);assertThrows(RuntimeException.class,()->service.register(new AuthDtos.RegisterRequest("a@b.com","Password123","Test")));verify(repo,never()).save(any());}}
